const root=path.resolve(__dirname,'../../..'), out=path.join(root,'.artifacts/deep-audit-round1-mobile','owner-probe-'+Date.now());fs.mkdirSync(out,{recursive:true});const home=path.join(out,'home');fs.mkdirSync(home);
const keep=new Set(['PATH','SYSTEMROOT','WINDIR','COMSPEC','PATHEXT','OS']);for(const k of Object.keys(process.env))if(!keep.has(k.toUpperCase()))delete process.env[k];for(const k of ['HOME','USERPROFILE','APPDATA','LOCALAPPDATA','TEMP','TMP','DSH_HOME','GRADLE_USER_HOME'])process.env[k]=home;
